mapper.select:
SELECT subject_sub_id   AS subjectSubId,
       subject_sub_name AS subjectSubName,
       subject_price    AS subjectPrice
FROM t_info_subject_edaban
WHERE subject_id = #{subjectId}
  AND subject_sub_id = #{subjectSubId}

mapper.update:
UPDATE t_info_lesson_fee
SET lsn_fee     = #{newFee},
    update_date = NOW()
WHERE lsn_fee_id = #{lsnFeeId}
  AND lesson_id  = #{lessonId}
